def calcular_precio(precio, descuento=10):
    # Escribe aquí: usa return para devolver precio - (precio * descuento / 100)
    return precio - (precio * descuento / 100)

print(calcular_precio(23000))       # usa el descuento por defecto (10%)
print(calcular_precio(23000, 45))   # usa 20%

def promedio_lista(numeros):
    return sum(numeros) / len(numeros)

notas = [7.0, 6.9, 7.0, 7.0]
resultado = promedio_lista(notas)
print(f"El promedio es {resultado}")

def contar_mayores(lista, limite):
    contador = 0
    # Escribe aquí: recorre la lista y cuenta los que sean mayores a 'limite'
    for e in lista:
        if e > limite:
           contador = contador + 1
    return contador

edades = [55, 22, 17, 30, 56, 5]
resultado = contar_mayores(edades, 18)
print(f"Hay {resultado} mayores de edad")

